class Solution {
public:
    int smallestValue(int n) {
        while (true) {
            int total = 0;
            int temp = n;
            for (int d = 2; d * d <= temp; ++d) {
                while (temp % d == 0) {
                    total += d;
                    temp /= d;
                }
            }
            if (temp > 1) total += temp;
            if (total == n) return n;
            n = total;
        }
    }
};

class Solution {
    public int smallestValue(int n) {
        while (true) {
            int total = 0;
            int temp = n;
            for (int d = 2; d * d <= temp; d++) {
                while (temp % d == 0) {
                    total += d;
                    temp /= d;
                }
            }
            if (temp > 1) total += temp;
            if (total == n) return n;
            n = total;
        }
    }
}

var smallestValue = function(n) {
    while (true) {
        let total = 0;
        let temp = n;
        for (let d = 2; d * d <= temp; d++) {
            while (temp % d === 0) {
                total += d;
                temp = Math.floor(temp / d);
            }
        }
        if (temp > 1) total += temp;
        if (total === n) return n;
        n = total;
    }
};
